package com.aivle.backend.journey;
import com.aivle.backend.common.entity.BaseEntity;import com.aivle.backend.project.entity.Project;import jakarta.persistence.*;import lombok.*;
@Entity(name="JourneyMarketingComparison") @Table(name="marketing_comparisons") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED)
public class JourneyMarketingComparison extends BaseEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="project_id",nullable=false)private Project project;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="concept_version_id",nullable=false)private ConceptVersion conceptVersion;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="workspace_id",nullable=false)private JourneyMarketingWorkspace workspace;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="run_id",nullable=false)private JourneyMarketingComparisonRun run;@Column(name="result_json",nullable=false,columnDefinition="TEXT")private String resultJson;public static JourneyMarketingComparison create(Project p,ConceptVersion c,JourneyMarketingWorkspace w,JourneyMarketingComparisonRun r,String result){JourneyMarketingComparison v=new JourneyMarketingComparison();v.project=p;v.conceptVersion=c;v.workspace=w;v.run=r;v.resultJson=result;return v;}}
